def check_girth(edges, n):
    """Check if graph has girth >= 7. Returns True if girth >= 7."""
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # BFS from each vertex to find shortest cycle
    for start in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[start] = 0
        queue = [start]

        for u in queue:
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif parent[u] != v and parent[v] != u:
                    # Found a cycle
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len == 3:
                        # More precise check for triangles
                        pass
                    if cycle_len >= 7:
                        continue
                    # Need to verify this is actually a cycle
                    # dist[u] + dist[v] + 1 is an upper bound on cycle length
                    # Let's find actual cycle length
                    path_u = []
                    path_v = []
                    x = u
                    while x != -1:
                        path_u.append(x)
                        x = parent[x]
                    x = v
                    while x != -1:
                        path_v.append(x)
                        x = parent[x]
                    # Find common ancestor
                    set_u = set(path_u)
                    for i, node in enumerate(path_v):
                        if node in set_u:
                            idx = path_u.index(node)
                            cycle = path_u[:idx+1] + path_v[:i+1]
                            if len(cycle) >= 2 and cycle[0] == cycle[-1]:
                                cycle = cycle[:-1]
                            actual_len = len(path_u[:idx]) + len(path_v[:i]) + 1
                            if actual_len >= 7:
                                continue
                            return False
    return True

def check_girth_fast(edges, n):
    """Faster girth check using adjacency matrix for small cycles."""
    # Build adjacency matrix
    adj = [[False] * n for _ in range(n)]
    for u, v in edges:
        adj[u][v] = True
        adj[v][u] = True

    # Check triangles
    for i in range(n):
        for j in range(i+1, n):
            if not adj[i][j]:
                continue
            for k in range(j+1, n):
                if adj[i][k] and adj[j][k]:
                    return False, 3

