                            [(i,j),(j,k),(k,m),(m,l),(l,i)],
                            [(i,j),(j,l),(l,k),(k,m),(m,i)],
                            [(i,j),(j,l),(l,m),(m,k),(k,i)],
                            [(i,j),(j,m),(m,k),(k,l),(l,i)],
                            [(i,j),(j,m),(m,l),(l,k),(k,i)],
                            [(i,k),(k,j),(j,l),(l,m),(m,i)],
                            [(i,k),(k,j),(j,m),(m,l),(l,i)],
                            [(i,k),(k,l),(l,j),(j,m),(m,i)],
                            [(i,k),(k,l),(l,m),(m,j),(j,i)],
                            [(i,k),(k,m),(m,j),(j,l),(l,i)],
                            [(i,k),(k,m),(m,l),(l,j),(j,i)],
                        ]
                        for ce in cycle_edges:
                            if all(adj[u][v] for u, v in ce):
                                return False, 5

    # Check 6-cycles
    # This is getting expensive. Let's use a different approach.
    # For each vertex, do BFS up to depth 3 and check for cycles
    for start in range(n):
        dist = [-1] * n
        dist[start] = 0
        queue = [start]

        for u in queue:
